def load_case014(root:Path):
    case=root/C14
    if not (case/'README.md').exists():return None
    spec=importlib.util.spec_from_file_location('case014_raw_display',case/'publication/scripts/derive.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
    data=read(case/'publication/summary/project.json');require(data==mod.derive(case),'Case014 display differs from raw records')
    manifest=read(case/'publication/provenance/PUBLICATION_MANIFEST.json')
    for rel,meta in manifest['files'].items():require(sha(case/rel)==meta['sha256'],'Case014 public source changed: '+rel)
    download=read(root/'downloads'/ARCHIVE.replace('.zip','.json'));require(download['filename']==ARCHIVE and download['bytes']==(root/'downloads'/ARCHIVE).stat().st_size and download['sha256']==sha(root/'downloads'/ARCHIVE),'Case014 download mismatch')
    paths=set(data['source_identity'])|{str(Path(v).relative_to(C14)) for v in [*SOURCE_COPIES.values(),*FIGURES.values()]}|{'publication/provenance/PUBLICATION_MANIFEST.json'}
    head=subprocess.run(['git','rev-parse','HEAD'],cwd=root,capture_output=True,text=True)
    revision=head.stdout.strip() if head.returncode==0 else None
    blob=subprocess.run(['git','show',str(revision)+':downloads/'+ARCHIVE],cwd=root,capture_output=True)
    pinned=revision if blob.returncode==0 and hashlib.sha256(blob.stdout).hexdigest()==download['sha256'] else None
    ref=pinned or 'refs/heads/case014/publication-p0-p2'
    return {**data,'sources':{C14+'/'+name:sha(case/name) for name in sorted(paths)},'download':download,
            'download_url':'https://github.com/Munsik-Kim/inference-lab/raw/'+ref+'/downloads/'+ARCHIVE,
            'download_git_revision':pinned,'download_link_scope':'matched committed blob' if pinned else 'uncommitted local preview; branch link becomes public after push',
            'evidence_kind':'RECALCULATED_RECORDED_P0_P1_P1B_P2_DENSE_BF16_REFERENCE'}

def a(url,label):return '<a href="'+escape(url,quote=True)+'">'+escape(label)+'</a>'
def readable(s,lang):
    if lang!='en':return s
    s=re.sub(r'\b(on|from|all|with|at|by|over|in|of|is|has|per|for|and|lower|crosses)(?=\d)',r'\1 ',s)
    return re.sub(r'(\d)(?=(?:books?|documents?|targets?|projections?|methods?|tokens?|comparisons?|paired|fixed|stored|seeds?|files?|intervals?|conditions?|groups?|resamples?|points?|bytes?|whole|models?|strengths?|positions?|independent)\b)',r'\1 ',s)
def table(headers,rows,label):
    return '<div class="scroll" role="region" tabindex="0" aria-label="'+escape(label,quote=True)+'"><table><thead><tr>'+''.join('<th scope="col">'+escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def metric(data,method,split='EVAL-ID'):return next(r for r in data['p2']['methods'] if r['method']==method and r['split']==split)
def home_case014(data,lang):
    ko=lang=='ko';txt=lambda k,e:k if ko else e;q=metric(data,'COMP_QUARTER');r=metric(data,'RTN');n=q['document_count']
    html='<section class="panel compensation-latest" id="compensation-study"><p class="eyebrow">CASE 014 · '+txt('최근 완료 연구','LATEST COMPLETED STUDY')+'</p><h2>'+a('case014.html#overview',TITLES[lang])+'</h2><p>'+txt('양자화된 모델의 실제 입력 경로를 따라 약하게 보정하고 같은 INT4 형식으로 저장하는 도구를 구현했습니다.','Built a pipeline that follows the model’s actual quantized inputs, fits weak compensation and stores it in the same INT4 format.')+'</p><ul class="case014-facts"><li><strong>'+f"{abs(q['PPL_relative_change'])*100:.2f}%"+'</strong> '+txt('PG19 PPL 감소 · RTN 대비','lower PG19 PPL versus RTN')+'</li><li><strong>'+f"{q['lower_documents']}/{n}"+'</strong> '+txt('문서 구간에서 NLL 개선','excerpts with lower NLL')+'</li><li><strong>'+txt('동일 INT4 저장량','Same INT4 storage')+'</strong></li></ul><p class="scope">'+txt('Qwen3-0.6B · 196 Transformer projections · 새 PG19 64책의256-token 구간. ArXiv에서는 같은 이득 미확인. BF16 복원 품질 평가이며 속도·VRAM 절감은 미측정.','Qwen3-0.6B ·196 Transformer projections ·256-token excerpts from64 fresh PG19 books. Gain not established on ArXiv. Dense BF16 reload quality; speed/VRAM savings unmeasured.')+'</p><div class="actions">'+a('case014.html#results',txt('결과 비교하기','Compare results'))+' · '+a('case014.html#implementation',txt('구현과 재현','Implementation and reproduction'))+' · '+a('case014.html#journey',txt('연구 과정','Research journey'))+'</div></section>'
    return readable(html,lang)

