    journey_rows=[['P0',txt('항상 보정하면 좋은가?','Does compensation always help?'),txt('유리수·finite4-code·무한 격자 dither를 분리. codec·대수 검산.','Separate rational/finite4-code/infinite-dither models; codec and algebra checks.')],['P1',txt('CAL 강도가 새 문서에도 좋은가?','Does CAL strength transfer?'),txt('CAL 선택은6/6 국소 SSE 악화. 사후0.25는6/6 개선.','CAL choices worsen local SSE6/6; post-hoc quarter improves6/6.')],['P1b',txt('적합과 선택 문서를 분리하면?','Separate fitting and selection?'),txt('독립 SSE 선택은 PG19 국소 전이 개선.0.25 대비 추가 NLL은 불확정;SHIFT 손실.','Independent SSE selection improves PG19 local transfer; extra NLL benefit over quarter inconclusive; SHIFT losses.')],['P2',txt('자체 경로 전층에서도 유효한가?','Does it help an actual whole model?'),txt('고정0.25의 PG19 전층 NLL 개선. ArXiv 한계 동시 관측.','Fixed quarter improves whole-model PG19 NLL; ArXiv limits remain.')]]
    journey=table(['Stage',txt('질문','Question'),txt('관측과 다음 단계','Observation and next step')],journey_rows,txt('P0에서 P2까지','P0 to P2'))+'<p>'+txt('P1b와P2는 이전 관측 후 설계한 별도 후속입니다. P1/P1b의 여섯 hybrid 개입은 하나의 전층 모델이 아니며, 효과나 표본 수를 P2와 합산하지 않습니다.','P1b/P2 were designed after prior observations. Six P1/P1b hybrid interventions are not one full model; effects and document counts are not pooled with P2.')+'</p><details><summary>'+txt('여섯 표적의 CAL 선택과 약한0.25 결과','Six CAL choices and weak-quarter outcomes')+'</summary>'+table(['Target','CAL alpha','Selected ΔSSE','Quarter ΔSSE'],[[x['target'].replace('model.layers.',''),x['selected_alpha'],f"{100*x['selected_SSE_change']:+.2f}%",f"{100*x['quarter_SSE_change']:+.2f}%"] for x in data['p1']['targets']],txt('32 EVAL문서의 국소 SSE','Local SSE on32 EVAL documents'))+fig('p1-transfer','CAL versus EVAL across all six targets',txt('전체 여섯 개입의 곡선입니다. 좋은 표적만 고르지 않았습니다.','Curves retain all six independent interventions.'))+'</details><details><summary>'+txt('P1b의 독립 SSE/NLL 선택과 전체 곡선','P1b independent SSE/NLL selection and full curves')+'</summary>'+table(['Target','OLD_FIT','SELECT_SSE','SELECT_NLL'],[[t.replace('model.layers.',''),v['OLD_FIT'],v['SELECT_SSE'],v['SELECT_NLL']] for t,v in sorted(data['p1b']['choices'].items())],'P1b choices')+fig('p1b-sse','All six P1b alpha/SSE curves',txt('서로 다른 prefix의 여섯 독립 개입입니다. 전층 모델 평균이 아닙니다.','Six independent interventions with different prefixes; not a whole-model average.'))+fig('p1b-nll','All six P1b alpha/NLL curves',txt('국소 SSE 선택과 gold NLL 선택은 목적이 다릅니다.','Local SSE and gold NLL optimize different objectives.'))+'</details><p>'+a('../sources/case014-stages.md.txt',txt('단계별 입력·원형 위치','Stage inputs and original locations'))+' · '+a('../sources/case014-p1-report-'+lang+'.md.txt','P1')+' · '+a('../sources/case014-p1b-report-'+lang+'.md.txt','P1b')+' · '+a('../sources/case014-p2-report-'+lang+'.md.txt','P2')+'</p>'
    out+=section(4,journey)
    command='OUT=$(mktemp -d)\npython3 -B '+C14+'/publication/scripts/derive.py --output "$OUT/display.json"\npython3 -B '+C14+'/publication/verify.py --output "$OUT/publication.json"\n"$CPU_PY" -B '+C14+'/publication/scripts/run_checks.py --output "$OUT/full-cpu" --tests'
    reproduction='<p>'+txt('처음 두 명령은 Python 표준 라이브러리만 사용합니다. 전체 재계산·검사는 NumPy와 CPU Torch가 필요합니다. 원 모델·개인 경로·인증키 없이 clone에서 실행할 수 있습니다.','The first two commands use Python stdlib. Full recalculation/tests need NumPy and CPU Torch. A clone needs no model, personal paths or credentials.')+'</p><pre>'+escape(command)+'</pre><p>'+a(data['download_url'],txt('통합 공개 ZIP','Unified public ZIP'))+' · '+a('../data/case014-download.json',txt('ZIP 크기·SHA256','ZIP bytes/SHA256'))+' · '+a('../sources/case014-reproduce.md.txt',txt('의존성과 전체 재현 범위','Dependencies and full reproduction scope'))+' · '+a('../sources/case014-audit.py.txt',txt('공개 CPU 검사 코드','Public CPU check code'))+'</p><p>'+txt('공개 검산은 저장 scalar와 구간·source 대응을 확인합니다. 과거 실행자의588 payload 검사나 GPU logits를 이번에 재실행한 것은 아닙니다. 새 모델 실험에는 외부 모델·원문/token·GPU 환경이 별도로 필요합니다.','Public checks verify saved scalars, intervals and source identities. They do not rerun the historical588-payload GPU check or logits. Model replay separately needs external weights/text/tokens/GPU environment.')+'</p>'
    out+=section(5,reproduction)
    equations='W[out,in], X/Z[in,tokens]\nG=ZZᵀ; lambda=.001 trace(G)/d_in\n(G+lambda I)Kᵀ=[W(X−Z)Zᵀ]ᵀ\nWstar=W+alpha K; What=reload(INT4(FP32(Wstar)))\nA=W(X−Z); C=alpha KZ; B=(What−Wstar)Z; B0=(What0−W)Z\nDelta=T_inherited+T_cancellation+T_requant\nT_inherited=||C||²−2<A,C>\nT_cancellation=2<B0,C>\nT_requant=||B−B0||²−2<R0−C,B−B0>'
    tech='<details><summary>'+txt('수식·shape·dtype·packed 저장','Equations, shapes, dtypes and packed storage')+'</summary><pre>'+escape(equations)+'</pre><p>'+txt('FP64 full-input Cholesky·row chunk128입니다. Ridge H는 projector로 가정하지 않습니다. 고정-B 반사실과 실제 연속 control을 구분하며, 저장 FP32 What의 대수와 BF16 실행 residual을 나눕니다. P2 B0는 각자 현재 Z의 국소 RTN입니다.','FP64 full-input Cholesky uses row chunk128. Ridge H is not assumed to be a projector. Fixed-B counterfactual and actual continuous controls differ; saved FP32 algebra and BF16 runtime residuals are separate. P2 B0 is local RTN on each current Z.')+'</p>'+a('../sources/case014-decompose.py.txt',txt('분해 구현','Decomposition source'))+'</details>'
    tech+='<details><summary>'+txt('문서 bootstrap과 사후 분석','Document bootstrap and post-hoc analyses')+'</summary><p>'+txt('P2 주 비교는 원 seed6101523의10,000회 paired 문서 재표집입니다. 구간은 원 CAL32·모델·강도에 조건화합니다. HALF와SHIFT는 보조 pointwise이며, P1b의 선택은 EVAL bootstrap 안에서 다시 고르지 않습니다. HALF−QUARTER는 원 검토 코드/seed가 없어 게시본에서 점추정만 재계산했습니다.','P2 primary uses10,000 paired document resamples, original seed6101523. Intervals condition on original CAL32/model/strength. HALF/SHIFT are auxiliary pointwise; P1b selections are not refit inside EVAL bootstrap. HALF−QUARTER is point-estimate-only here because original reviewer code/seed were unavailable.')+'</p>'+fig('paired','Paired document NLL changes',txt('0 아래는 RTN보다 낮은 NLL,0 위는 높은 NLL입니다. 전체 문서를 남겼습니다.','Below0 means lower NLL than RTN; above0 means higher. All documents are retained.'))+'</details>'
    costrows=[[s['method'],s['files'],f"{s['artifact_bytes']:,}",f"{R:.3f}s"] for s,R in [(x,data['p2']['resources']['stage_seconds_inclusive'][x['method']+'_build']) for x in data['p2']['storage']]]
    tech+='<details><summary>'+txt('저장량과 offline 구축 비용','Storage and offline construction cost')+'</summary>'+table(['Method','Projection files','Core bytes','Offline build'],costrows,'INT4 core files and offline costs')+'<p>'+txt('Header7,056 + scale27,525,120 + code220,200,960B. 공통 tensor311,296,000B는 별도이며 tie는 한 번만 셉니다. RTN은 CAL 정보·적합 비용이 없는 단순 기준선입니다. 구축은 capture·solve·진단·I/O를 포함하며 serving 지연이 아닙니다.','Headers7,056 + scales27,525,120 + codes220,200,960B. Common311,296,000B tensors are separate, ties counted once. RTN is a simple baseline without CAL fitting cost. Build includes capture/solve/diagnostics/I/O, not serving latency.')+'</p>'+fig('cost','Core storage and offline construction cost',txt('Projection 저장 장부와 offline 비용입니다. 전체 checkpoint 크기·GPU peak·실행 가속으로 읽지 않습니다.','Projection accounting and offline cost, not full checkpoint bytes, GPU peak or serving acceleration.'))+'</details>'
    tech+='<details><summary>'+txt('부호·bound·원형과 검산 범위','Signs, bounds, preserved originals and audit scope')+'</summary><p>'+txt('P1 실측 방향2304/2304 일치·bound2195개 인증. P1b fresh EVAL1535/1536 일치·1396개 인증입니다. 인증 실패를 미측정 또는 방향 반대로 바꾸지 않습니다. 과거 문서는 바이트 보존하고 단계별 닫힌 view로 복원해 검사합니다. 개인 model path는 별도 sanitized 사본으로 표시했습니다.','P1 measured directions agree2304/2304, with2195 bound certifications. P1b fresh EVAL agrees1535/1536, with1396 certifications. Lack of certification is not missing measurement or a reversed sign. Historical documents are preserved and checked in closed restored stage views; one local model path has a separately labeled sanitized copy.')+'</p>'+a('../data/case014.json',txt('전체 표시값과 source SHA','All display values and source SHA'))+'</details>'
    out+=section(6,tech)
    refs='<p>'+a('../sources/case014-report-'+lang+'.md.txt',txt('정식 통합 보고서','Unified formal report'))+' · '+a('../sources/case014-notice.md.txt','NOTICE')+' · '+a('../sources/case014-source-audit.json.txt',txt('기존 문헌 확인 기록','Historical source audit'))+'</p><p>'+txt('Guo의 보정·mean-square 연구와 HALF 전이 실험이 선행 결과입니다. 이 프로젝트는 ridge/RTN reference와 capture·직렬화·평가·검산 도구를 구현했습니다. 공식 QEP 전체 재현이나 새 quantizer를 주장하지 않습니다.','Guo’s compensation/mean-square work and HALF-transfer experiments are prior results. This project implements ridge/RTN reference capture, serialization, evaluation and audit tools, not complete official QEP reproduction or a new quantizer.')+'</p><p>'+a('https://arxiv.org/html/2610.16020v1','Guo2026 v1')+' · '+a('https://huggingface.co/Qwen/Qwen3-0.6B','Qwen3-0.6B')+'</p><p>'+txt('Codex가 구현·분석·문서화를 보조했습니다. 별도 CPU 계산 코드의 검산은 사람의 독립 심사·외부 GPU 재현·저자 승인과 구분합니다. 이번 게시 작업의 새 GPU 추론·K 적합·재양자화는0회입니다.','Codex assisted implementation, analysis and writing. Separate CPU calculation paths are distinct from independent human peer review, external GPU reproduction or author approval. New GPU inference/K fitting/re-quantization during publication:0.')+'</p>'
